import {serializeThemePrism} from './theme-sharing.js';
import {downloadThemeData} from './theme-creator.js';
export async function mountShopScreen({document,themePrisms,shopCatalogue},library){
 const el=id=>document.getElementById(id),items=await shopCatalogue.list();let pending=null,disposed=false;
 function say(text){el('shop-status').textContent=text;}
 function render(){const list=el('shop-list'),query=el('shop-search').value.trim().toLowerCase();list.replaceChildren();for(const item of items.filter(item=>(item.theme.name+' '+item.description).toLowerCase().includes(query))){const card=document.createElement('article');card.className='shop-card';const preview=document.createElement('div');preview.className='shop-swatches';for(const key of ['bg','raised','accent','primary']){const dot=document.createElement('span');dot.style.backgroundColor=item.theme.tokens[key];preview.append(dot);}const name=document.createElement('h3'),description=document.createElement('p'),meta=document.createElement('small'),actions=document.createElement('div');name.textContent=item.theme.name;description.textContent=item.description;meta.textContent='Free · Theme Prism · '+new TextEncoder().encode(serializeThemePrism(item.theme)).length.toLocaleString()+' bytes';for(const [label,action] of [['Review & install',()=>{pending=item.theme;el('shop-review-name').textContent=pending.name;el('shop-review-license').textContent=pending.license;el('shop-review').hidden=false;el('shop-review').scrollIntoView({block:'nearest'});}],['Download',()=>downloadThemeData(document,item.theme.id+'.prism.json',serializeThemePrism(item.theme))]]){const button=document.createElement('button');button.textContent=label;button.onclick=action;if(label==='Review & install'&&themePrisms.list().some(p=>p.id===item.theme.id)){button.textContent='Installed';button.disabled=true;}actions.append(button);}card.append(preview,name,description,meta,actions);list.append(card);}el('shop-empty').hidden=list.children.length>0;}
 el('shop-search').oninput=render;el('shop-install').onclick=()=>{if(!pending)return;try{themePrisms.install(pending);library.refresh();el('shop-review').hidden=true;const name=pending.name;pending=null;render();say(name+' installed. Activate it from Prisms when you choose.');}catch(error){say(error.message);}};el('shop-cancel').onclick=()=>{pending=null;el('shop-review').hidden=true;say('Nothing installed.');};
 const change=()=>{if(!disposed)render();};document.addEventListener('prismy-prisms-changed',change);render();return {dispose(){disposed=true;document.removeEventListener('prismy-prisms-changed',change);el('shop-search').oninput=null;el('shop-install').onclick=null;el('shop-cancel').onclick=null;el('shop-list').replaceChildren();}};
}
